#!/usr/bin/env node
/**
 * calendar-extractor — generated by JavisSkills/skill-creator
 * Triggered by openclaw cron OR by the LLM on user-typed commands.
 *
 * Usage:
 *   node calendar-extractor.js <userId>
 *   node calendar-extractor.js --help
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { sanitizeId, safeUserPath, readJson, writeJson } = require('./data');

if (process.argv.includes('--help')) {
  console.log('Usage: node calendar-extractor.js <userId>');
  process.exit(0);
}

const userId = sanitizeId(process.argv[2]);

async function main() {
  let transcriptText = '';
  for await (const chunk of process.stdin) transcriptText += chunk;
  if (!process.env.HTTP_SOURCE_URL) {
    throw new Error('HTTP_SOURCE_URL env var is required when external-http data source is wired. Either set it or remove the fetch() call below.');
  }
  const res = await fetch(process.env.HTTP_SOURCE_URL);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  const data = await res.json();
  const output = JSON.stringify({ transcript: transcriptText, external: data }, null, 2);
  console.log(output);
}

main().catch((err) => {
  console.error('❌', err.message);
  process.exit(1);
});
